 static byte[] sse(){try{return ("data: "+new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("delta",new JSONObject().put("content",new JSONObject().put("eidolon_chat",1).put("messages",new JSONArray()).put("exchange",new JSONObject().put("decision","wait")).toString()))))+"\n\ndata: [DONE]\n\n").getBytes("UTF-8");}catch(Exception e){throw new IllegalStateException(e);}}
 static void checkEmpty(JSONObject s,JSONObject f,JSONObject b,List<ChatStore.Message> h,long now)throws Exception{if(selected(eval(s,f,b,h,now))!=null)throw new AssertionError("empty wake");}
 static JSONObject extract(String s,String marker)throws Exception{String start="BEGIN_"+marker+"\n",end="\nEND_"+marker;int at=s.indexOf(start)+start.length();return new JSONObject(s.substring(at,s.indexOf(end,at)));}
